"""Automation API — execution history, file downloads, manual triggers.

Provides:
* GET  /api/chat-sessions/{id}/automation       — panel payload (Manus-style)
* GET  /api/automations/{id}/executions         — list past runs
* GET  /api/automations/executions/{id}         — get a single execution
* GET  /api/automations/executions/{id}/details — full run + files + conversation_id
* GET  /api/automations/executions/{id}/files   — list files generated by a run
* GET  /api/automations/files/{id}/download     — download a generated file
* POST /api/automations/{id}/run                — trigger an immediate run
* POST /api/automations/{id}/recompute          — recompute next_run_at
* POST /api/automations/{id}/toggle             — pause/resume
* POST /api/automations/{id}/skip-confirmation  — toggle skip_confirmation
* POST /api/automations/parse-schedule          — parse a schedule string client-side
"""

from __future__ import annotations

