router = APIRouter(prefix="/automations", tags=["automations"])
logger = logging.getLogger(__name__)


def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def _assert_tenant(obj, user: User) -> None:
    """Raise 404 if ``obj`` doesn't belong to ``user``'s org.

    Returns 404 (not 403) so the mere existence of another tenant's
    resources can't be inferred — closes the IDOR vector on the
    automation read/download endpoints.
    """
    org_id = getattr(user, "org_id", None)
    if org_id is not None and getattr(obj, "org_id", None) != org_id:
        raise HTTPException(status_code=404, detail="Not found")


_PREVIEWABLE_FILE_TYPES = {
    "csv", "docx", "gif", "htm", "html", "jpeg", "jpg", "json", "md",
    "pdf", "png", "pptx", "svg", "txt", "webp", "xlsx",
}


def _serialize_automation_file(file_record: AutomationFile) -> dict:
    """Return one stable deliverable payload for run, chat, and file views."""
    file_type = (file_record.file_type or Path(file_record.name).suffix).lower().lstrip(".")
    file_url = file_record.file_url or f"/api/automations/files/{file_record.id}/download"
    mime_type = file_record.mime_type or mimetypes.guess_type(file_record.name)[0]
    created_date = getattr(file_record, "created_date", None)
    if hasattr(created_date, "isoformat"):
        created_date = created_date.isoformat()

    return {
        "id": file_record.id,
        "automation_file_id": file_record.id,
        "name": file_record.name,
        "file_name": file_record.name,
        "type": file_type,
        "file_type": file_type,
        "mime_type": mime_type,
        "size": file_record.size,
        "file_size": file_record.size,
        "url": file_url,
        "file_url": file_url,
        "preview_url": f"/api/automations/files/{file_record.id}/preview",
        "has_preview": file_type in _PREVIEWABLE_FILE_TYPES,
        "source": "automation_file",
        "created_date": created_date,
    }


def _chat_message_artifacts_for_files(files: list[AutomationFile]) -> list[dict]:
    """Map ``AutomationFile`` rows onto the artifact shape the chat surface
    already understands.

    The chat-side ``ArtifactCardList`` was built around artifact payloads from
    live chat runs. The deliverable serializer (above) is the same shape plus
    a few extras (``has_preview``, ``created_date``) the card list gracefully
    ignores, so we use it directly and add the chat-friendly ``title`` alias
    so cards keep showing the file name when ``title`` is what they read.
    """
    return [
        {
            "id": f.id,
            "artifact_id": f.id,
            "automation_file_id": f.id,
            "title": f.name,
            "name": f.name,
            "file_name": f.name,
            "type": (f.file_type or Path(f.name).suffix).lower().lstrip("."),
            "file_type": (f.file_type or Path(f.name).suffix).lower().lstrip("."),
            "file_size": f.size,
            "size": f.size,
            "url": f.file_url or f"/api/automations/files/{f.id}/download",
            "file_url": f.file_url or f"/api/automations/files/{f.id}/download",
            "preview_url": f"/api/automations/files/{f.id}/preview",
            "has_preview": (f.file_type or Path(f.name).suffix).lower().lstrip(".")
            in _PREVIEWABLE_FILE_TYPES,
            "source": "automation_file",
        }
        for f in files
    ]


# ---------------------------------------------------------------------------
# Schedules
# ---------------------------------------------------------------------------

class ParseScheduleRequest(BaseModel):
    schedule: str
    timezone: str | None = None


@router.post("/parse-schedule")
def parse_schedule_endpoint(req: ParseScheduleRequest):
    """Parse a free-form schedule string into a cron expression + next run time.

    ``timezone`` (optional IANA name, e.g. "Asia/Shanghai") controls which
    timezone the cron is interpreted in; the returned ``next_run_at`` is
    always UTC-naive so the client can display it in the user's locale.
    """
    from app.services.schedule_parser import parse_schedule, next_run_at, describe_schedule
    try:
        cron = parse_schedule(req.schedule)
        nxt = next_run_at(cron, tz_name=req.timezone)
        return {
            "success": True,
            "cron": cron,
            "next_run_at": nxt.isoformat(),
            "description": describe_schedule(cron),
            "timezone": req.timezone or "UTC",
        }
    except Exception as e:
        return {"success": False, "error": str(e)}


# ---------------------------------------------------------------------------
# Per-session panel (Manus-style "Scheduled" side panel)
# ---------------------------------------------------------------------------

@router.get("/by-session/{session_id}")
def get_automation_by_session(
    session_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Return the AutomationTask linked to a chat session, plus its recent
    executions. Used by the Manus-style "Scheduled" side panel that appears
    only in chat sessions that have an automation.

    Returns ``{"task": null}`` if the session has no automation — the
    frontend uses this to decide whether to render the Scheduled button.

    Scoped to the caller's org so one tenant can't enumerate another's
    automations by guessing session ids.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.session_id == session_id,
        AutomationTask.org_id == user.org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).order_by(AutomationTask.created_date.desc()).first()
    if not task:
        return {"task": None, "executions": []}

    # Attach the last N executions with their file counts.
    rows = db.query(AutomationExecution).filter(
        AutomationExecution.automation_task_id == task.id,
        AutomationExecution.is_deleted == False,  # noqa: E712
    ).order_by(AutomationExecution.created_date.desc()).limit(20).all()

    executions = []
    for r in rows:
        d = r.to_dict()
        files = db.query(AutomationFile).filter(
            AutomationFile.execution_id == r.id,
            AutomationFile.is_deleted == False,  # noqa: E712
        ).all()
        d["files"] = [_serialize_automation_file(f) for f in files]
        d["file_count"] = len(files)
        # Phase 5 (Tier A #2): surface the quality-gate decision + held_back
        # flag so the Scheduled panel can explain why a completed run has no
        # deliverable file (low-confidence output was held back).
        _qg = (
            (r.output_data or {}).get("quality_gate")
            if isinstance(r.output_data, dict) else None
        )
        d["quality_gate"] = _qg
        d["held_back"] = bool(_qg and not _qg.get("passed", True))
        # Per-run conversation id — surfaced explicitly for the run-log
        # "Open in chat" deep-link (the executor creates one conversation
        # per execution, stored in output_data.conversation_id).
        d["conversation_id"] = (
            (r.output_data or {}).get("conversation_id")
            if isinstance(r.output_data, dict) else None
        )
        executions.append(d)

    return {
        "task": task.to_dict(),
        "executions": executions,
    }


@router.get("/by-session/{session_id}/files")
def list_files_by_session(
    session_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Return the AutomationTask (if any) for this chat session plus every file
    reachable from it.

    Primary list: AI-generated ``AutomationFile`` rows from all executions of the
    session's task. ``_source="ai_generated"`` so the UI can label them.
    Secondary list: any ``UserFile`` rows uploaded to this session, with
    ``_source="uploaded"`` (kept so chat uploads still surface even when the
    session has no automation).

    Used by the chat-side "Files in this task" panel so triggered automation
    runs surface their generated artifacts even though executions aren't
    visible in chat. Scoped to the caller's org, mirroring ``/by-session``.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.session_id == session_id,
        AutomationTask.org_id == user.org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).order_by(AutomationTask.created_date.desc()).first()

    files: list[dict] = []

    if task:
        rows = db.query(AutomationFile).filter(
            AutomationFile.automation_task_id == task.id,
            AutomationFile.is_deleted == False,  # noqa: E712
        ).order_by(AutomationFile.created_date.desc()).limit(200).all()
        for f in rows:
            d = _serialize_automation_file(f)
            d["_source"] = "ai_generated"
            d["execution_id"] = f.execution_id
            files.append(d)

    # UserFile uploads for this session (secondary; lets manual uploads show
    # even when no task is linked to the session).
    user_rows = db.query(UserFile).filter(
        UserFile.session_id == session_id,
        UserFile.is_deleted == False,  # noqa: E712
    ).order_by(UserFile.updated_date.desc()).limit(200).all()
    for u in user_rows:
        d = u.to_dict()
        d["_source"] = "uploaded"
        files.append(d)

    return {
        "task_id": task.id if task else None,
        "task_name": task.name if task else None,
        "files": files,
    }


# ---------------------------------------------------------------------------
# Executions
# ---------------------------------------------------------------------------

@router.get("/{task_id}/executions")
def list_executions(
    task_id: str,
    limit: int = Query(20, ge=1, le=100),
    db: Session = Depends(get_db),
):
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")

    rows = db.query(AutomationExecution).filter(
        AutomationExecution.automation_task_id == task_id,
        AutomationExecution.is_deleted == False,
    ).order_by(AutomationExecution.created_date.desc()).limit(limit).all()

    out = []
    for r in rows:
        d = r.to_dict()
        # Attach file count + urls.
        files = db.query(AutomationFile).filter(
            AutomationFile.execution_id == r.id,
            AutomationFile.is_deleted == False,
        ).all()
        d["files"] = [_serialize_automation_file(f) for f in files]
        d["file_count"] = len(files)
        if d.get("status") == "failed" and d.get("error"):
            d["error_code"] = classify_run_failure_reason(d["error"])
        # Phase 5 (Tier A #2): surface the quality-gate decision + held_back
        # flag so the execution list (dedicated automation page) can explain
        # a completed run with no deliverable file.
        _qg = (
            (r.output_data or {}).get("quality_gate")
            if isinstance(r.output_data, dict) else None
        )
        d["quality_gate"] = _qg
        d["held_back"] = bool(_qg and not _qg.get("passed", True))
        # Per-run conversation id (the executor creates one AgentConversation
        # per execution). Surfaced explicitly so the run-log "Open in chat"
        # deep-link doesn't have to dig through the output_data blob.
        d["conversation_id"] = (
            (r.output_data or {}).get("conversation_id")
            if isinstance(r.output_data, dict) else None
        )
        out.append(d)
    return {"executions": out, "total": len(out)}


@router.get("/executions/{execution_id}")
def get_execution(execution_id: str, db: Session = Depends(get_db)):
    row = db.query(AutomationExecution).filter(
        AutomationExecution.id == execution_id,
    ).first()
    if not row:
        raise HTTPException(status_code=404, detail="Execution not found")
    d = row.to_dict()
    files = db.query(AutomationFile).filter(
        AutomationFile.execution_id == execution_id,
        AutomationFile.is_deleted == False,
    ).all()
    d["files"] = [_serialize_automation_file(f) for f in files]
    return d


@router.get("/executions/{execution_id}/files")
def list_execution_files(execution_id: str, db: Session = Depends(get_db)):
    files = db.query(AutomationFile).filter(
        AutomationFile.execution_id == execution_id,
        AutomationFile.is_deleted == False,
    ).all()
    return {"files": [_serialize_automation_file(f) for f in files]}


@router.get("/executions/{execution_id}/details")
def get_execution_details(
    execution_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Return one execution with its full output, files, and the linked
    conversation_id. Used by the Scheduled panel's "expand past run" view
    so the user can read the run's full report and download the file(s).
    """
    row = db.query(AutomationExecution).filter(
        AutomationExecution.id == execution_id,
        AutomationExecution.is_deleted == False,  # noqa: E712
    ).first()
    if not row:
        raise HTTPException(status_code=404, detail="Execution not found")
    _assert_tenant(row, user)
    d = row.to_dict()
    files = db.query(AutomationFile).filter(
        AutomationFile.execution_id == execution_id,
        AutomationFile.is_deleted == False,  # noqa: E712
    ).all()
    d["files"] = [_serialize_automation_file(f) for f in files]
    if d.get("status") == "failed" and d.get("error"):
        d["error_code"] = classify_run_failure_reason(d["error"])
    # Surface the conversation_id from output_data so the panel can offer
    # "open in chat" without the client having to dig through nested JSON.
    d["conversation_id"] = (
        (row.output_data or {}).get("conversation_id")
        if isinstance(row.output_data, dict) else None
    )
    d["agent_id"] = (
        (row.output_data or {}).get("agent_id")
        if isinstance(row.output_data, dict) else None
    )
    d["agent_name"] = (
        (row.output_data or {}).get("agent_name")
        if isinstance(row.output_data, dict) else None
    )
    # Which prior run's output was carried as context (cross-run continuity).
    # None on the first run; otherwise lets the panel show "built on run X"
    # and link to it.
    d["carried_context_from"] = (
        (row.output_data or {}).get("carried_context_from")
        if isinstance(row.output_data, dict) else None
    )
    # Phase 5 (Tier A #2): surface the quality-gate decision so the panel can
    # show a "file held back by quality gate" notice when the deliverable
    # wasn't shipped. ``held_back`` is a convenience boolean for the client.
    _qg = (
        (row.output_data or {}).get("quality_gate")
        if isinstance(row.output_data, dict) else None
    )
    d["quality_gate"] = _qg
    d["held_back"] = bool(_qg and not _qg.get("passed", True))
    return d


# Poll interval for the live SSE stream. Uses async sleep (not time.sleep) so
# the event-loop thread is released between polls — a sync generator would
# hold a threadpool worker for the stream's entire lifetime (up to 1h).
SSE_POLL_INTERVAL = 1.5


def _sse(obj: dict) -> str:
    """Format one SSE data frame."""
    return f"data: {json.dumps(obj, default=str)}\n\n"


async def _execution_event_stream(execution_id: str):
    """Generate SSE ``data: {json}`` strings tailing one execution's live
    progress. Yields ``activity_steps`` / ``phase`` deltas, then a terminal
    ``done`` or ``error`` event when the run reaches a terminal status, then
    stops.

    Polls the execution row every ~1.5s using a short-lived session per
    iteration (never holds a session across the sleep). Best-effort: any DB
    error yields an error event and stops so the client's EventSource
    reconnects / falls back to polling. Mirrors the sandbox job-events stream.
    """
    last_steps_sig = None
    last_phase = None
    deadline = time.time() + 3600  # hard cap 1h per stream
    while time.time() < deadline:
        s = SessionLocal()
        try:
            ex = s.query(AutomationExecution).filter(
                AutomationExecution.id == execution_id,
            ).first()
            if not ex:
                yield _sse({"type": "error", "message": "Execution not found"})
                return
            steps = ex.activity_steps or []
            sig = json.dumps(steps, default=str, sort_keys=True)
            if sig != last_steps_sig:
                last_steps_sig = sig
                yield _sse({"type": "activity_steps", "steps": steps})
            phase = ex.current_phase
            if phase != last_phase:
                last_phase = phase
                if phase:
                    yield _sse({"type": "phase", "state": phase})
            status = ex.status
            if status in ("completed", "failed", "skipped"):
                if status == "completed":
                    yield _sse({
                        "type": "done",
                        "content": (ex.output_text or "")[:4000],
                        "execution_id": execution_id,
                    })
                else:
                    yield _sse({
                        "type": "error",
                        "message": (ex.error or "Run failed")[:500],
                        "status": status,
                        "execution_id": execution_id,
                    })
                return
        except Exception as e:  # noqa: BLE001
            yield _sse({"type": "error", "message": f"stream error: {e}"})
            return
        finally:
            try:
                s.close()
            except Exception:
                pass
        await asyncio.sleep(SSE_POLL_INTERVAL)


@router.get("/executions/{execution_id}/events/stream")
async def stream_execution_events(execution_id: str):
    """Server-Sent Events stream of one execution's live progress.

    Mirrors the sandbox job-events stream. The Scheduled panel consumes this
    with ``EventSource`` while a run is queued/running and falls back to 30s
    polling when SSE fails. See ``_execution_event_stream`` for the event
    format.
    """
    # Existence check so a missing id 404s immediately (cleaner for the
    # client than an empty/error stream).
    s = SessionLocal()
    try:
        found = s.query(AutomationExecution).filter(
            AutomationExecution.id == execution_id,
        ).first()
    finally:
        try:
            s.close()
        except Exception:
            pass
    if not found:
        raise HTTPException(status_code=404, detail="Execution not found")

    return StreamingResponse(
        _execution_event_stream(execution_id),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


class SkipConfirmationRequest(BaseModel):
    skip: bool


@router.post("/{task_id}/skip-confirmation")
def set_skip_confirmation(
    task_id: str, req: SkipConfirmationRequest, db: Session = Depends(get_db)
):
    """Toggle the Manus-style "Always skip" confirmations flag on a task."""
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    task.skip_confirmation = "true" if req.skip else "false"
    task.updated_date = datetime.utcnow()
    db.commit()
    return {
        "success": True,
        "skip_confirmation": str(task.skip_confirmation).lower() in ("1", "true", "yes"),
    }


# ---------------------------------------------------------------------------
# Manual trigger
# ---------------------------------------------------------------------------

class RunRequest(BaseModel):
    note: Optional[str] = None


@router.post("/{task_id}/run")
async def run_now(task_id: str, db: Session = Depends(get_db)):
    """Manually trigger an immediate run. Returns the new execution id."""
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    from app.services.automation_dispatcher import trigger_now
    exec_id = await trigger_now(task_id)
    if not exec_id:
        raise HTTPException(status_code=500, detail="Failed to start execution")
    return {"success": True, "execution_id": exec_id}


# ---------------------------------------------------------------------------
# Session adoption (Manus UX — one chat per automation)
# ---------------------------------------------------------------------------


def _ensure_task_chat_session(db: Session, task: AutomationTask) -> tuple[str, bool]:
    """Return ``(session_id, created)`` for a dedicated per-task chat.

    Thin delegation to ``app.services.automation_sessions.ensure_task_chat_session``
    so the executor (services layer) can call the same logic without
    importing from the router (which would invert the dependency). The
    full implementation — including project-resolved tagging and drift
    reconciliation — lives in the service.
    """
    from app.services.automation_sessions import ensure_task_chat_session
    return ensure_task_chat_session(db, task)


@router.post("/{task_id}/ensure-session")
def ensure_session(task_id: str, db: Session = Depends(get_db)):
    """Adopt (or create) a dedicated chat session for an automation.

    The Manus-style UX expects every automation to live in its own
    chat, named after the task. Tasks created before the
    one-task-one-session migration may still be sharing a generic
    session (``"test"`` etc.). This endpoint either:

    * returns the existing matching session (no-op), or
    * creates a fresh ChatSession + AgentConversation pair, links
      it to the task, and returns the new session id.

    The frontend ``runNow`` calls this BEFORE ``POST /run`` so the
    resulting ``Open run`` message lands in the dedicated chat, not
    whatever legacy session the task inherited.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    session_id, created = _ensure_task_chat_session(db, task)
    return {"success": True, "session_id": session_id, "created": created}


@router.post("/{task_id}/recompute")
def recompute_next_run_endpoint(task_id: str, db: Session = Depends(get_db)):
    """Recompute and persist the next_run_at for a task."""
    from app.services.automation_dispatcher import recompute_next_run
    nxt = recompute_next_run(task_id)
    if not nxt:
        raise HTTPException(
            status_code=400,
            detail="Task has no valid schedule to recompute",
        )
    return {"success": True, "next_run_at": nxt.isoformat()}


