_PREVIEW_RESPONSE_HEADERS = {
    "Cache-Control": "private, max-age=300",
    "Content-Security-Policy": (
        "sandbox; default-src 'none'; img-src data: https:; "
        "style-src 'unsafe-inline'; font-src data: https:"
    ),
    "X-Content-Type-Options": "nosniff",
}


@router.post("/files/{file_id}/preview-token")
def mint_file_preview_token(
    file_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Mint a short-lived signed token so iframe previews (which cannot send
    Authorization headers) can load the preview endpoint via ``?token=``."""
    from app.services.preview_tokens import mint_preview_token

    file_row = db.query(AutomationFile).filter(
        AutomationFile.id == file_id,
        AutomationFile.is_deleted == False,  # noqa: E712
    ).first()
    if not file_row:
        raise HTTPException(status_code=404, detail="File not found")
    _assert_tenant(file_row, user)
    token = mint_preview_token(file_id=file_id, user_id=str(user.id))
    return {
        "token": token,
        "url": f"/api/automations/files/{file_id}/preview?token={token}",
    }


@router.get("/files/{file_id}/preview")
def preview_automation_file(
    file_id: str,
    token: Optional[str] = Query(None),
    db: Session = Depends(get_db),
    user: Optional[User] = Depends(get_current_user_optional),
):
    """Render a generated automation file inline without exposing disk paths.

    Accepts either the Bearer header (fetch/XHR) or a signed ``?token=``
    minted by ``POST /files/{id}/preview-token`` (iframe/img navigation).
    """
    from app.services.preview_tokens import verify_preview_token

    file_row = db.query(AutomationFile).filter(
        AutomationFile.id == file_id,
        AutomationFile.is_deleted == False,  # noqa: E712
    ).first()
    if not file_row:
        raise HTTPException(status_code=404, detail="File not found")

    if user is None and token:
        uid = verify_preview_token(token, file_id)
        if uid:
            candidate = db.get(User, uid)
            if candidate is not None and not getattr(candidate, "is_anonymous", False):
                user = candidate
    if user is None:
        raise HTTPException(status_code=401, detail="Authentication required")
    _assert_tenant(file_row, user)

    path = Path(file_row.file_path or "")
    if not path.exists():
        raise HTTPException(status_code=410, detail="File no longer exists on disk")

    file_type = (file_row.file_type or path.suffix).lower().lstrip(".")
    if file_type not in _PREVIEWABLE_FILE_TYPES:
        raise HTTPException(status_code=415, detail="Preview is not available for this file type")

    if file_type in {"docx", "pptx", "xlsx"}:
        from app.services.artifacts.preview_builder import convert_to_preview

        # Pass the file-extension type ("docx" / "pptx" / "xlsx"), not the
        # MIME string — convert_to_preview dispatches on the extension-style
        # identifier and would silently return None for a MIME string,
        # which then 415s ("Preview conversion is unavailable"). The user
        # reported this with "Daily Sales Data Sync.docx" showing
        # "Preview unavailable (HTTP 404)" in the chat right pane — the
        # 404 was actually from the fallback renderer hitting a separate
        # broken endpoint; the underlying 415 here is what we just fixed.
        converted = convert_to_preview(
            path.read_bytes(),
            file_row.name,
            file_type,
        )
        if converted is None:
            raise HTTPException(status_code=415, detail="Preview conversion is unavailable")
        # convert_to_preview returns (preview_data, preview_file_name,
        # preview_mime_type). The route was previously written against an
        # unapplied dataclass (converted.ext / converted.data / ...) that
        # never landed, so any successful conversion crashed here with
        # AttributeError. Unpack the tuple explicitly.
        preview_bytes, preview_name, preview_mime = converted
        return Response(
            content=preview_bytes,
            media_type=preview_mime,
            headers={
                **_PREVIEW_RESPONSE_HEADERS,
                "Content-Disposition": f'inline; filename="{preview_name}"',
            },
        )

    return FileResponse(
        path=str(path),
        media_type=file_row.mime_type or mimetypes.guess_type(file_row.name)[0]
        or "application/octet-stream",
        filename=file_row.name,
        content_disposition_type="inline",
        headers=_PREVIEW_RESPONSE_HEADERS,
    )


@router.get("/files/{file_id}/download")
def download_file(
    file_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    file_row = db.query(AutomationFile).filter(
        AutomationFile.id == file_id,
        AutomationFile.is_deleted == False,
    ).first()
    if not file_row:
        raise HTTPException(status_code=404, detail="File not found")
    _assert_tenant(file_row, user)
    path = Path(file_row.file_path or "")
    if not path.exists():
        raise HTTPException(status_code=410, detail="File no longer exists on disk")
    return FileResponse(
        path=str(path),
        media_type=file_row.mime_type or "application/octet-stream",
        filename=file_row.name,
    )


# ---------------------------------------------------------------------------
# Status toggle
# ---------------------------------------------------------------------------

class ToggleRequest(BaseModel):
    status: str  # "active" or "paused"


@router.post("/{task_id}/toggle")
def toggle_status(task_id: str, req: ToggleRequest, db: Session = Depends(get_db)):
    """Pause/resume an automation. If resuming, recompute next_run_at."""
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    new_status = req.status
    if new_status not in ("active", "paused", "failed", "completed"):
        raise HTTPException(status_code=400, detail=f"Invalid status: {new_status}")
    task.status = new_status
    task.updated_date = datetime.utcnow()
    db.commit()
    if new_status == "active" and task.cron_expression:
        from app.services.automation_dispatcher import recompute_next_run
        nxt = recompute_next_run(task_id)
        if nxt:
            return {
                "success": True,
                "status": new_status,
                "next_run_at": nxt.isoformat(),
            }
    return {
        "success": True,
        "status": new_status,
        "next_run_at": task.next_run_at.isoformat() if task.next_run_at else None,
    }


@router.delete("/{task_id}")
def delete_automation(task_id: str, db: Session = Depends(get_db)):
    """Soft-delete an automation task. Used by the Manus-style
    'Delete schedule' action in the Scheduled side panel.

    Also clears the chat_session → task link by stamping a sentinel on
    the session's metadata so the Scheduled button disappears for the
    originating chat.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    task.is_deleted = True
    task.status = "deleted"
    task.updated_date = datetime.utcnow()
    db.commit()
    return {"success": True, "id": task_id}


# ── Nightly forecast bootstrap ─────────────────────────────────────────


@router.post("/bootstrap-nightly-forecast")
def bootstrap_nightly_forecast(
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Create the idempotent nightly forecast automation task.

    Ensures:
      1. The 12 Ecisco BI forecast targets exist (via seed_ecisco_forecast_targets)
      2. The automation_runtime_agent exists for this (org, app)
      3. An AutomationTask with cron=0 2 * * *, skip_confirmation=true exists

    Returns the existing task if already created. Idempotent.
    """
    from app.config import settings

    if not getattr(settings, "NIGHTLY_FORECAST_ENABLED", True):
        raise HTTPException(status_code=403, detail="Nightly forecast is disabled")

    from app.services.automation_runtime import ensure_automation_runtime_agent
    from app.services.forecasting.seed_ecisco_targets import (
        seed_ecisco_forecast_targets,
        discover_and_seed_sku_targets,
    )

    org_id = getattr(user, "org_id", None) or "default-org"
    app_id = getattr(user, "app_id", None) or "default-app"
    cron = getattr(settings, "NIGHTLY_FORECAST_CRON", "0 2 * * *")

    # 1. Ensure targets exist (idempotent)
    seed_ecisco_forecast_targets(db, org_id=org_id, app_id=app_id)
    # 1b. Discover and seed ERP SKU targets (idempotent)
    sku_count = discover_and_seed_sku_targets(db, org_id=org_id, app_id=app_id)
    if sku_count:
        logger.info("[bootstrap] Seeded %d new ERP SKU targets for org=%s", sku_count, org_id)

    # 2. Ensure runtime agent exists (idempotent)
    runtime = ensure_automation_runtime_agent(db, org_id, app_id)

    # 3. Find or create the automation task (idempotent by name + org)
    existing = db.query(AutomationTask).filter(
        AutomationTask.name == "Nightly Ecisco BI Forecast",
        AutomationTask.org_id == org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if existing:
        return {"task_id": existing.id, "status": "exists", "cron": cron}

    task = AutomationTask(
        name="Nightly Ecisco BI Forecast",
        type="scheduled",
        description=(
            "Silent nightly ML forecast for all 12 Ecisco BI dashboard "
            "products. Writes to forecast_runs; dashboard reads via "
            "/forecast-base-batch."
        ),
        org_id=org_id,
        app_id=app_id,
        agent_id=runtime.id,
        created_by_id=getattr(user, "id", None),
        schedule=cron,
        cron_expression=cron,
        timezone="UTC",
        skip_confirmation="true",
        output_format="json",
        prompt=(
            "Run the `forecast_run` tool with no arguments (target_id=null) "
            "to refresh forecasts for all active targets in this org. "
            "Do not chat, summarize, or output any narrative — just call the "
            "tool, report success/failure counts, and end."
        ),
        status="active",
    )
    db.add(task)
    db.commit()
    db.refresh(task)
    return {"task_id": task.id, "status": "created", "cron": cron}


